<?phpsession_start();require_once "db.php";// Admin Securityif (!isset($_SESSION['admin_id'])) {    header("Location: index.php");    exit();}// Attendance Report Query$query = "SELECT            s.roll_number,            s.student_name,            sub.subject_name,            COUNT(a.attendance_id) AS total_classes,            COUNT(CASE WHEN a.status = 'Present' THEN 1 END) AS present,            COUNT(CASE WHEN a.status = 'Absent' THEN 1 END) AS absent          FROM attendance a          JOIN students s ON a.student_id = s.student_id          JOIN subjects sub ON a.subject_id = sub.subject_id          GROUP BY s.student_id, s.roll_number, s.student_name,                   sub.subject_id, sub.subject_name          ORDER BY s.roll_number";$result = pg_query($conn, $query);function e($value) {    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>SmartAttend | Student Attendance Report</title><style>* {    margin: 0;    padding: 0;    box-sizing: border-box;    font-family: Arial, sans-serif;}body {    background: #0875c9;    min-height: 100vh;    color: #263653;}/* HEADER */.header {    position: relative;    text-align: center;    color: white;    padding: 35px 15px;}.header h1 {    font-size: 32px;    margin-bottom: 10px;}.header p {    color: #dcecff;    font-size: 14px;}.back-btn {    position: absolute;    top: 28px;    left: 25px;    background: rgba(255,255,255,0.18);    color: white;    text-decoration: none;    padding: 11px 18px;    border-radius: 8px;    font-size: 14px;}.back-btn:hover {    background: rgba(255,255,255,0.30);}/* MAIN CONTAINER */.report-container {    max-width: 1450px;    margin: 15px auto;    padding: 0 25px 45px;}.report-card {    background: white;    padding: 28px;    border-radius: 15px;    box-shadow: 0 5px 20px rgba(0,0,0,0.12);}.report-title {    margin-bottom: 8px;    font-size: 23px;    color: #263653;}.report-subtitle {    color: #8993a5;    font-size: 14px;    margin-bottom: 25px;}/* TABLE */.table-responsive {    width: 100%;    overflow-x: auto;}table {    width: 100%;    border-collapse: collapse;    min-width: 750px;}thead {    background: #159bd1;    color: white;}th {    padding: 16px 13px;    text-align: left;    font-size: 14px;    white-space: nowrap;}td {    padding: 16px 13px;    border-bottom: 1px solid #e9edf2;    font-size: 14px;    color: #46536a;}tbody tr:hover {    background: #f3f9ff;}/* PERCENTAGE BADGES */.percentage {    display: inline-block;    padding: 7px 12px;    border-radius: 20px;    font-weight: bold;    font-size: 12px;}.good {    background: #dcfce7;    color: #15803d;}.average {    background: #fef3c7;    color: #b45309;}.low {    background: #fee2e2;    color: #dc2626;}/* EMPTY MESSAGE */.empty {    text-align: center;    padding: 35px;    color: #8993a5;}/* FOOTER */.footer {    text-align: center;    color: #dcecff;    font-size: 13px;    margin-top: 25px;}/* RESPONSIVE */@media(max-width: 700px) {    .header {        padding: 25px 15px;    }    .header h1 {        font-size: 24px;        margin-top: 15px;    }    .back-btn {        position: static;        display: inline-block;        margin-bottom: 15px;    }    .report-container {        padding: 0 13px 30px;    }    .report-card {        padding: 17px;    }    .report-title {        font-size: 20px;    }}</style></head><body><!-- HEADER --><header class="header"><a href="dashboard.php" class="back-btn">    Back to Dashboard</a><h1>Student Attendance Report</h1><p>View and monitor student attendance records</p></header><!-- REPORT SECTION --><div class="report-container"><div class="report-card">    <h2 class="report-title">Attendance Overview</h2>    <p class="report-subtitle">        Student-wise and subject-wise attendance details.    </p>    <div class="table-responsive">        <table>            <thead>                <tr>                    <th>Roll Number</th>                    <th>Student Name</th>                    <th>Subject</th>                    <th>Total Classes</th>                    <th>Present</th>                    <th>Absent</th>                    <th>Percentage</th>                </tr>            </thead>            <tbody>            <?php if ($result && pg_num_rows($result) > 0): ?>                <?php while ($row = pg_fetch_assoc($result)): ?>                    <?php                    $total = (int)$row['total_classes'];                    $present = (int)$row['present'];                    $absent = (int)$row['absent'];                    $percentage = $total > 0                        ? round(($present / $total) * 100, 2)                        : 0;                    if ($percentage >= 75) {                        $badge = "good";                    } elseif ($percentage >= 50) {                        $badge = "average";                    } else {                        $badge = "low";                    }                    ?>                    <tr>                        <td><?php echo e($row['roll_number']); ?></td>                        <td><?php echo e($row['student_name']); ?></td>                        <td><?php echo e($row['subject_name']); ?></td>                        <td><?php echo $total; ?></td>                        <td><?php echo $present; ?></td>                        <td><?php echo $absent; ?></td>                        <td>                            <span class="percentage <?php echo $badge; ?>">                                <?php echo $percentage; ?>%                            </span>                        </td>                    </tr>                <?php endwhile; ?>            <?php else: ?>                <tr>                    <td colspan="7" class="empty">                        No attendance records found.                    </td>                </tr>            <?php endif; ?>            </tbody>        </table>    </div></div><div class="footer">    © 2026 SmartAttend · College Attendance Management System</div></div></body></html>